export const CHANNELS=['NEFT','IMPS','ACH','NACH','ECS','RTGS'];
export function paymentChannel(description){let s=String(description||'').toUpperCase();let found=CHANNELS.filter(c=>new RegExp('(?:^|[^A-Z])'+c+'(?=$|[^A-Z]|(?:CR|DR|CREDIT|DEBIT|RTN|RET|RETURN)(?=$|[^A-Z]))').test(s));return found.length===1?found[0]:'Other'}
export function channelSummary(rows){return [...CHANNELS,'Other'].map(channel=>{let matched=rows.filter(t=>paymentChannel(t.description)===channel),included=matched.filter(t=>!t.review);return{channel,rows:matched,count:matched.length,review:matched.length-included.length,debit:included.reduce((n,t)=>n+(t.debit||0),0),credit:included.reduce((n,t)=>n+(t.credit||0),0)}})}
const DAY=86400000;
export function bankDate(value){let s=String(value||'').trim(),m,y,month,d;const months=['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'];if((m=s.match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})$/))){[,y,month,d]=m}else if((m=s.match(/^(\d{1,2})[-/.](\d{1,2})[-/.](\d{2,4})$/))){[,d,month,y]=m}else if((m=s.match(/^(\d{1,2})[- /]?([a-z]{3})[- /]?(\d{2,4})$/i))){d=m[1];month=months.indexOf(m[2].toLowerCase())+1;y=m[3]}else return null;y=+y<100?2000+(+y):+y;month=+month;d=+d;let stamp=Date.UTC(y,month-1,d),date=new Date(stamp);return date.getUTCFullYear()===y&&date.getUTCMonth()===month-1&&date.getUTCDate()===d?stamp:null}
const iso=stamp=>new Date(stamp).toISOString().slice(0,10);
export function balanceAnalytics(rows,{start,end,opening=null}={}){let dated=rows.map((t,i)=>({...t,stamp:bankDate(t.date),index:i})),invalid=dated.filter(t=>t.stamp===null).length;dated=dated.filter(t=>t.stamp!==null);let known=dated.filter(t=>!t.review&&Number.isFinite(t.balance)),observedAverage=known.length?known.reduce((s,t)=>s+t.balance,0)/known.length:null;
if(!dated.length)return{daily:[],monthly:[],average:null,observedAverage,days:0,missing:0,invalid,start:null,end:null,error:'No valid transaction dates are available.'};let descending=dated[0].stamp>dated.at(-1).stamp;dated.sort((a,b)=>a.stamp-b.stamp||(descending?b.index-a.index:a.index-b.index));let first=dated[0].stamp,last=dated.at(-1).stamp,from=start?bankDate(start):first,to=end?bankDate(end):last;if(from===null||to===null||to<from)return{daily:[],monthly:[],average:null,observedAverage,error:'Enter a valid period with the end on or after the start.',invalid};if((to-from)/DAY>36600)return{daily:[],monthly:[],average:null,observedAverage,error:'Choose a balance period of 100 years or less.',invalid};known=known.filter(t=>t.stamp>=from&&t.stamp<=to);observedAverage=known.length?known.reduce((s,t)=>s+t.balance,0)/known.length:null;let byDate=new Map();for(let t of dated)byDate.set(t.stamp,!t.review&&Number.isFinite(t.balance)?t.balance:null);let carry=Number.isFinite(opening)?opening:null;for(let t of dated){if(t.stamp<from)carry=!t.review&&Number.isFinite(t.balance)?t.balance:null}let daily=[];for(let stamp=from;stamp<=to;stamp+=DAY){if(byDate.has(stamp))carry=byDate.get(stamp);daily.push({date:iso(stamp),balance:carry,carried:!byDate.has(stamp)})}let missing=daily.filter(d=>d.balance===null).length,sum=daily.reduce((n,d)=>n+(d.balance??0),0),monthly=[];for(let key of [...new Set(daily.map(d=>d.date.slice(0,7)))]){let ds=daily.filter(d=>d.date.startsWith(key)),unknown=ds.filter(d=>d.balance===null).length;monthly.push({month:key,days:ds.length,missing:unknown,average:unknown||invalid?null:ds.reduce((n,d)=>n+d.balance,0)/ds.length})}return{daily,monthly,average:missing||invalid?null:sum/daily.length,observedAverage,days:daily.length,missing,invalid,start:iso(from),end:iso(to),error:null}}
